-- V41-C3R0/C3R1: Configuration baseline freeze and 438-key Runtime Definition Closure.
-- Generated by scripts/configuration/build-v41-c3r0-c3r1-closure.py.
-- IMPORTANT: structural PROPOSED definitions remain migration_authorized=false/admin_editable=false.
-- Existing reviewed/migration-authorized definitions are never downgraded by this migration.

on conflict(definition_key) do update set
 display_name=excluded.display_name,
 owner=case when runtime_config_definitions.migration_authorized then runtime_config_definitions.owner else excluded.owner end,
 domain_owner=case when runtime_config_definitions.migration_authorized then runtime_config_definitions.domain_owner else excluded.domain_owner end,
 authority_class=excluded.authority_class,scope=excluded.scope,scope_ref=excluded.scope_ref,data_type=excluded.data_type,unit=excluded.unit,risk=excluded.risk,
 mutability=case when runtime_config_definitions.migration_authorized then runtime_config_definitions.mutability else excluded.mutability end,
 consumer_contract=case when runtime_config_definitions.migration_authorized then runtime_config_definitions.consumer_contract else excluded.consumer_contract end,
 target_mutability=excluded.target_mutability,target_consumer_contract=excluded.target_consumer_contract,environment_applicability=excluded.environment_applicability,
 validation_rule=case when runtime_config_definitions.migration_authorized then runtime_config_definitions.validation_rule else excluded.validation_rule end,
 requires_approval=case when runtime_config_definitions.migration_authorized then runtime_config_definitions.requires_approval else excluded.requires_approval end,
 admin_editable=case when runtime_config_definitions.migration_authorized then runtime_config_definitions.admin_editable else false end,
 initial_seed=excluded.initial_seed,introduced_version=coalesce(runtime_config_definitions.introduced_version,excluded.introduced_version),
 ui_metadata=runtime_config_definitions.ui_metadata || excluded.ui_metadata,config_set_key=coalesce(runtime_config_definitions.config_set_key,excluded.config_set_key),
 review_status=case when runtime_config_definitions.migration_authorized then runtime_config_definitions.review_status else 'PROPOSED' end,
 migration_authorized=runtime_config_definitions.migration_authorized,
 schema_version=greatest(runtime_config_definitions.schema_version,excluded.schema_version),source_ref=excluded.source_ref,source_fingerprint=excluded.source_fingerprint,synchronized_at=now();

comment on table runtime_config_definitions is 'Runtime Configuration source-definition materialization. V41-C3R1 provides source-controlled definition coverage for every RUNTIME_CONFIG target; only reviewed consumer migrations may set migration_authorized=true.';

-- C3R1 safety: structural definitions MUST NOT accidentally become editable/authorized.
do $$ declare v_count integer; begin select count(*) into v_count from runtime_config_definitions where source_ref='contracts/current/configuration/definitions/runtime-target-definition-baseline-v41-c3r1.json' and review_status='PROPOSED' and (migration_authorized=true or admin_editable=true); if v_count<>0 then raise exception 'C3R1_STRUCTURAL_DEFINITION_AUTHORITY_LEAK: %',v_count; end if; end $$;
