  ('adapter-actions.mcp.one-per-task','One MCP action per task','ADAPTER_ACTION','ADAPTER_ACTION','RUNTIME_TUNABLE','COMPONENT','ADAPTER_ACTION','BOOLEAN','boolean','MEDIUM','HOT_IMMEDIATE','RUNTIME_SNAPSHOT','HOT_IMMEDIATE','RUNTIME_SNAPSHOT','["PRD","UAT","SIT","QA","DEV","LOCAL"]'::jsonb,'{}'::jsonb,true,true,'{"strategy":"CURRENT_EFFECTIVE_STARTUP_VALUE","purpose":"migration-bootstrap-only"}'::jsonb,'V40-9','{"categoryId":"adapter-action-mcp","displayName":"One MCP action per task","description":"Controls MCP idempotency scope for newly evaluated terminal task callbacks.","recommended":"Enabled for deterministic one-action-per-task behavior","effect":"Next MCP idempotency-key generation","impactPositive":"Prevents duplicate MCP work for repeated evaluation of the same task.","impactTradeoff":"Disabling permits distinct MCP actions for repeated task evaluation and increases downstream workload.","advancedKeyVisible":true,"categoryDisplayName":"Adapter Action MCP","categoryDescription":"MCP action orchestration runtime controls.","categoryOrder":52}'::jsonb,'RUNTIME/ADAPTER_ACTION/SYSTEM','MIGRATION_READY',true,4,'contracts/current/configuration/definitions/runtime-target-definition-baseline-v41-c3r1.json','834f5849fef9d37ab4ab4735283fdf7acc0a6451464e3687b11616088f09bd28'),
