  ('adapter-actions.worker.initial-backoff','Adapter worker initial retry delay','ADAPTER_ACTION','ADAPTER_ACTION','RUNTIME_TUNABLE','COMPONENT','ADAPTER_ACTION','DURATION','duration','MEDIUM','HOT_NEXT_CYCLE','RUNTIME_SNAPSHOT','HOT_NEXT_CYCLE','RUNTIME_SNAPSHOT','["PRD","UAT","SIT","QA","DEV","LOCAL"]'::jsonb,'{"minimum":"PT0.001S","maximum":"PT1H"}'::jsonb,true,true,'{"strategy":"CURRENT_EFFECTIVE_STARTUP_VALUE","purpose":"migration-bootstrap-only"}'::jsonb,'V40-9','{"categoryId":"adapter-action-worker","displayName":"Adapter worker initial retry delay","description":"Initial delay used when an adapter action enters retry waiting after a worker failure or expired lease.","recommended":"PT5S–PT1M","effect":"Next retry scheduling decision","impactPositive":"Provides backpressure while allowing transient failures to recover quickly.","impactTradeoff":"Long delays slow recovery; very short delays can create retry pressure.","advancedKeyVisible":true,"categoryDisplayName":"Adapter Action Worker","categoryDescription":"External worker retry and lease recovery controls.","categoryOrder":51}'::jsonb,'RUNTIME/ADAPTER_ACTION/SYSTEM','MIGRATION_READY',true,4,'contracts/current/configuration/definitions/runtime-target-definition-baseline-v41-c3r1.json','56e20adb35b43fa3697dd11cd9350fe3951f7b94d99d6d38098d72502209b51d'),
  ('adapter-actions.worker.max-attempts','Adapter worker maximum attempts','ADAPTER_ACTION','ADAPTER_ACTION','RUNTIME_TUNABLE','COMPONENT','ADAPTER_ACTION','INTEGER','attempts','MEDIUM','HOT_NEXT_CYCLE','RUNTIME_SNAPSHOT','HOT_NEXT_CYCLE','RUNTIME_SNAPSHOT','["PRD","UAT","SIT","QA","DEV","LOCAL"]'::jsonb,'{"minimum":1,"maximum":20}'::jsonb,true,true,'{"strategy":"CURRENT_EFFECTIVE_STARTUP_VALUE","purpose":"migration-bootstrap-only"}'::jsonb,'V40-9','{"categoryId":"adapter-action-worker","displayName":"Adapter worker maximum attempts","description":"Maximum governed attempts captured for newly created adapter actions.","recommended":"2–5","effect":"New adapter action creation; existing actions retain their stored attempt cap","impactPositive":"More attempts improve resilience to transient worker/provider failures.","impactTradeoff":"Higher values delay terminal failure and can increase provider load.","advancedKeyVisible":true,"categoryDisplayName":"Adapter Action Worker","categoryDescription":"External worker retry and lease recovery controls.","categoryOrder":51}'::jsonb,'RUNTIME/ADAPTER_ACTION/SYSTEM','MIGRATION_READY',true,4,'contracts/current/configuration/definitions/runtime-target-definition-baseline-v41-c3r1.json','30b50627ce1e310ab72afcbb66552f04c8423a8d46a4c74cd6d717d2f04a41a4'),
